begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(15);
insert into auth.users(id,email,email_confirmed_at) values('02000000-0000-4000-8000-000000000001','vault-admin@example.test',now()),('02000000-0000-4000-8000-000000000002','vault-member@example.test',now());
insert into auth.sessions(id,user_id,created_at,updated_at) values('12000000-0000-4000-8000-000000000001','02000000-0000-4000-8000-000000000001',now(),now()),('12000000-0000-4000-8000-000000000002','02000000-0000-4000-8000-000000000002',now(),now());
insert into profiles(id,username,display_name,role,policy_version,policy_accepted_at) values('02000000-0000-4000-8000-000000000001','vault_admin','Admin','admin','2026-11-01',now()),('02000000-0000-4000-8000-000000000002','vault_member','Member','member','2026-11-01',now());
update workspace_settings set limits=limits||'{"file_bytes":20,"html_bytes":20,"total_bytes":100,"member_bytes":50,"folder_depth":2}'::jsonb;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"02000000-0000-4000-8000-000000000002","session_id":"12000000-0000-4000-8000-000000000002","aal":"aal1"}',true);
select lives_ok($$select request_upload('a.txt',19,'text/plain')$$,'file allowed at limit minus one');
select lives_ok($$select request_upload('b.txt',20,'text/plain')$$,'file allowed at size limit');
select throws_ok($$select request_upload('big.txt',21,'text/plain')$$,'23514',null,'file rejected over size limit');
select throws_ok($$select request_upload('bad.exe',1,'text/plain')$$,'23514',null,'extension and MIME allowlist enforced');
select throws_ok($$select request_upload('c.txt',12,'text/plain')$$,'23514',null,'pending reservations count against member quota');
select lives_ok($$select request_upload('c.txt',11,'text/plain')$$,'reservation allowed exactly at personal quota');
select throws_ok($$select request_upload('d.txt',1,'text/plain')$$,'23514',null,'personal quota blocks next action');
select lives_ok($$insert into storage.objects(bucket_id,name,metadata) select 'cq-vault',path,'{"size":19,"mimetype":"text/plain"}' from files where name='a.txt'$$,'reserved object accepts matching metadata');
select throws_ok($$insert into storage.objects(bucket_id,name,metadata) values('cq-vault','unreserved.txt','{"size":1,"mimetype":"text/plain"}')$$,'42501',null,'unreserved Storage path rejected');
select throws_ok($$insert into storage.objects(bucket_id,name,metadata) select 'cq-vault',path,'{"size":20,"mimetype":"text/plain"}' from files where name='c.txt'$$,'42501',null,'mismatched actual size rejected');
select is((select count(*) from storage.objects where bucket_id='cq-vault'),0::bigint,'raw authenticated Storage download is denied');
select throws_ok($$select finalize_upload((select id from files limit 1),auth.uid())$$,'42501',null,'client cannot finalize without Edge validation');
select lives_ok($$select create_folder('Root')$$,'member can create root folder');
select lives_ok($$select create_folder('Child',(select id from folders where name='Root'))$$,'folder allowed at depth limit');
select throws_ok($$select create_folder('Too deep',(select id from folders where name='Child'))$$,'23514',null,'folder rejected over depth limit');
select * from finish();
rollback;
